import '@toeverything/theme/style.css'
import * as Y from 'yjs'

// ─── Types ────────────────────────────────────────────────────────────────────

interface InitOptions {
  container: HTMLElement
  noteId: string
  mode?: 'page' | 'edgeless'
  theme?: 'light' | 'dark'
  readonly?: boolean
  onLoad?: () => Promise<string | null>
  onSave?: (snapshot: string) => Promise<void>
  onImageUpload?: (file: File) => Promise<string>
}

interface EditorInstance {
  destroy: () => void
  getSnapshot: () => string | null
  setTheme: (theme: 'light' | 'dark') => void
  setReadonly: (readonly: boolean) => void
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function u8ToBase64(u8: Uint8Array): string {
  let s = ''
  for (let i = 0; i < u8.length; i++) s += String.fromCharCode(u8[i])
  return btoa(s)
}

function base64ToU8(b64: string): Uint8Array {
  const s = atob(b64)
  const u8 = new Uint8Array(s.length)
  for (let i = 0; i < s.length; i++) u8[i] = s.charCodeAt(i)
  return u8
}

function applyTheme(element: HTMLElement, theme: 'light' | 'dark') {
  if (theme === 'dark') {
    element.setAttribute('data-color-mode', 'dark')
    element.setAttribute('data-theme', 'dark')
  } else {
    element.removeAttribute('data-color-mode')
    element.removeAttribute('data-theme')
  }
}

// ─── Main init function ───────────────────────────────────────────────────────

async function initEditor(opts: InitOptions): Promise<EditorInstance> {
  const {
    container,
    noteId,
    mode = 'page',
    theme = 'light',
    readonly = false,
    onLoad,
    onSave,
    onImageUpload,
  } = opts

  // ── 1. Register BlockSuite web components ────────────────────────────────
  const [
    { AffineEditorContainer },
    { DocCollection, Schema },
    { AffineSchemas },
    blocksEffects,
    presetsEffects,
  ] = await Promise.all([
    import('@blocksuite/presets'),
    import('@blocksuite/store'),
    import('@blocksuite/blocks'),
    import('@blocksuite/blocks/effects'),
    import('@blocksuite/presets/effects'),
  ])

  if (!(window as any).__bsEditorEffectsLoaded) {
    try { blocksEffects.effects() } catch {}
    try { presetsEffects.effects() } catch {}
    ;(window as any).__bsEditorEffectsLoaded = true
  }

  // ── 2. Create Yjs doc ────────────────────────────────────────────────────
  const persistDoc = new Y.Doc()

  // ── 3. Load existing content via onLoad callback ─────────────────────────
  if (onLoad) {
    try {
      const snapshot = await onLoad()
      if (snapshot) {
        const binary = base64ToU8(snapshot)
        if (binary.length > 10) {
          Y.applyUpdate(persistDoc, binary, 'remote')
          console.log('[ConferioEditor] Loaded snapshot:', binary.length, 'bytes')
        }
      }
    } catch (e) {
      console.warn('[ConferioEditor] onLoad failed:', e)
    }
  }

  // ── 4. Setup BlockSuite collection ───────────────────────────────────────
  const schema = new Schema().register(AffineSchemas)
  const collection = new DocCollection({
    schema,
    id: noteId,
    // @ts-ignore — use our Yjs doc as the collection root
    doc: persistDoc,
  })
  collection.meta.initialize()

  let doc = collection.getDoc(noteId)
  if (!doc) doc = collection.createDoc({ id: noteId })

  doc.load(() => {
    if (!doc!.root) {
      const pageId = doc!.addBlock('affine:page', {})
      doc!.addBlock('affine:surface', {}, pageId)
      const noteBlock = doc!.addBlock('affine:note', {}, pageId)
      doc!.addBlock('affine:paragraph', {}, noteBlock)
    }
  })

  // ── 5. Mount editor ──────────────────────────────────────────────────────
  const editor = new AffineEditorContainer()
  editor.doc = doc
  editor.mode = mode

  applyTheme(editor as unknown as HTMLElement, theme)

  if (readonly) {
    doc.awarenessStore.setReadonly(doc.blockCollection, true)
  }

  editor.style.cssText = 'width:100%;height:100%;display:block;'
  container.innerHTML = ''
  container.appendChild(editor as unknown as Node)

  // ── 6. Handle image uploads via blobSync ────────────────────────────────
  // BlockSuite uploads images to its own blob storage by default.
  // We intercept and redirect to the provided onImageUpload callback.
 if (onImageUpload && collection.blobSync) {
  // Store original methods by extracting them first
  const bs = collection.blobSync
  const originalSet = (key: string, value: Blob) => bs.set(key, value)
  const originalGet = (key: string) => bs.get(key)

  // Override set with type assertion
  ;(bs.set as any) = async (key: string, blob: Blob) => {
    try {
      const ext = blob.type.split('/')[1] || 'png'
      const file = new File([blob], `image.${ext}`, { type: blob.type })
      const url = await onImageUpload(file)

      // Call original
      const id = await originalSet(key, blob)
      console.log('[ConferioEditor] Image uploaded to:', url, 'blobId:', id)

      const blobId = id
      const imageUrl = url
      
      // Override get for this specific blob
      ;(bs.get as any) = async (getKey: string) => {
        if (getKey === blobId) {
          try {
            const res = await fetch(imageUrl)
            return res.blob()
          } catch {
            return originalGet(getKey)
          }
        }
        return originalGet(getKey)
      }

      return id
    } catch (e) {
      console.error('[ConferioEditor] Image upload failed:', e)
      return originalSet(key, blob)
    }
  }
}

  // ── 7. Watch for changes and save ───────────────────────────────────────
  let saveTimer: ReturnType<typeof setTimeout> | null = null
  let hasLocalChanges = false

  const doSave = async () => {
    if (!onSave) return
    try {
      const state = Y.encodeStateAsUpdate(persistDoc)
      if (state.length <= 10) return
      const snapshot = u8ToBase64(state)
      await onSave(snapshot)
      console.log('[ConferioEditor] ✓ Saved', state.length, 'bytes')
    } catch (e) {
      console.error('[ConferioEditor] Save error:', e)
    }
  }

  const scheduleLocalSave = () => {
    hasLocalChanges = true
    if (saveTimer) clearTimeout(saveTimer)
    saveTimer = setTimeout(doSave, 2000)
  }

  const watchDoc = (ydoc: Y.Doc, label: string) => {
    ydoc.on('update', (update: Uint8Array, origin: any) => {
      // Sync into persistDoc
      try { Y.applyUpdate(persistDoc, update, 'sync') } catch {}
      // Only save for local changes
      const isLocal = !['remote', 'sync', 'persist'].includes(String(origin))
      if (isLocal) {
        console.log(`[ConferioEditor] ${label} local update size=${update.length}`)
        scheduleLocalSave()
      }
    })
  }

  watchDoc(persistDoc, 'persistDoc')

  // Also watch subdocs — BlockSuite creates subdocs for surfaces etc.
  persistDoc.on('subdocs', ({ added }: { added: Set<Y.Doc> }) => {
    added.forEach(subdoc => watchDoc(subdoc, `subdoc:${subdoc.guid}`))
  })
  persistDoc.getSubdocs().forEach(subdoc => watchDoc(subdoc, `subdoc:${subdoc.guid}`))

  // ── 8. Save on page visibility change / unload ──────────────────────────
  const onVisibilityChange = () => {
    if (document.visibilityState === 'hidden' && hasLocalChanges) doSave()
  }
  document.addEventListener('visibilitychange', onVisibilityChange)

  // ── 9. Return instance API ───────────────────────────────────────────────
  return {
    destroy: () => {
      if (saveTimer) clearTimeout(saveTimer)
      if (hasLocalChanges) doSave()
      document.removeEventListener('visibilitychange', onVisibilityChange)
      try { (editor as unknown as HTMLElement).remove() } catch {}
      persistDoc.destroy()
    },

    getSnapshot: () => {
      const state = Y.encodeStateAsUpdate(persistDoc)
      return state.length > 10 ? u8ToBase64(state) : null
    },

    setTheme: (t: 'light' | 'dark') => {
      applyTheme(editor as unknown as HTMLElement, t)
    },

    setReadonly: (r: boolean) => {
      doc!.awarenessStore.setReadonly(doc!.blockCollection, r)
    },
  }
}

// ─── Export as global for script tag usage ────────────────────────────────────
;(window as any).ConferioEditor = { initEditor }

export { initEditor }
export type { InitOptions, EditorInstance }